begin;
select plan(27);
select has_table('public','scenario_auction_items','auction item table exists');
select has_table('public','game_auctions','runtime auction table exists');
select has_table('public','game_auction_bids','auction bids table exists');
select has_function('public','open_game_auction',array['text','uuid'],'open RPC exists');
select has_function('public','record_game_auction_bid',array['text','integer','integer','uuid'],'bid RPC exists');
select has_function('public','close_game_auction',array['text','uuid'],'close RPC exists');
select has_function('public','close_game_auction_no_sale',array['text','uuid'],'no-sale RPC exists');
select ok(not has_table_privilege('authenticated','public.game_auction_bids','SELECT'),'bids are not directly readable');
select is((select count(*) from public.scenario_auction_items where scenario_version_id='e0000000-0000-0000-0000-000000000015'),1::bigint,'TEST01 has one auction item');
select throws_ok($$update public.scenario_auction_items set title='changed' where id='f0000000-0000-0000-0000-000000000211'$$,'P0001','PUBLISHED_SCENARIO_IMMUTABLE','published auction item is immutable');

insert into auth.users(id,aud,role,email,is_anonymous) values
 ('00000000-0000-0000-0000-000000000701','authenticated','authenticated','auction-staff@example.test',false),
 ('00000000-0000-0000-0000-000000000702','authenticated','authenticated','auction-other@example.test',false);
insert into public.staff_members(id,auth_user_id,display_name,active) values ('40000000-0000-0000-0000-000000000701','00000000-0000-0000-0000-000000000701','Auction Staff',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000701',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000701","role":"authenticated","is_anonymous":false}',true);
select throws_ok($$select * from public.open_game_auction('TEST01','70000000-0000-0000-0000-000000000701')$$,'P0001','AUCTION_PHASE_REQUIRED','auction phase required');
reset role;
update public.games set lifecycle='live',narrative_phase='auction' where code='TEST01';
set local role authenticated;
select is((select status from public.open_game_auction('TEST01','70000000-0000-0000-0000-000000000701')),'open','active Staff opens auction');
select is((select count(*) from public.open_game_auction('TEST01','70000000-0000-0000-0000-000000000701')),1::bigint,'open is idempotent');
select is((select amount from public.record_game_auction_bid('TEST01',1,7,'70000000-0000-0000-0000-000000000702')),7,'valid bid accepted');
select is((select amount from public.record_game_auction_bid('TEST01',2,9,'70000000-0000-0000-0000-000000000703')),9,'higher bid accepted');
select throws_ok($$select * from public.record_game_auction_bid('TEST01',3,8,'70000000-0000-0000-0000-000000000704')$$,'P0001','BID_NOT_HIGH_ENOUGH','bid must exceed highest');
select throws_ok($$select * from public.record_game_auction_bid('TEST01',3,21,'70000000-0000-0000-0000-000000000705')$$,'P0001','INSUFFICIENT_TABLE_COINS','bid cannot exceed table balance');
select throws_ok($$select * from public.transition_game_narrative_phase('TEST01','auction','deliberation','70000000-0000-0000-0000-000000000706')$$,'P0001','AUCTION_NOT_SETTLED','deliberation blocked before settlement');
select is((select winning_table_number from public.close_game_auction('TEST01','70000000-0000-0000-0000-000000000707')),2,'highest bid wins deterministically');
select is((select count(*) from public.close_game_auction('TEST01','70000000-0000-0000-0000-000000000707')),1::bigint,'close is idempotent');
select is((select count(*) from realtime.messages where topic='game:a0000000-0000-0000-0000-000000000050' and event='auction_changed'),4::bigint,'open bids and close emit wake-ups');
reset role;
select is((select sum(delta) from public.table_coin_ledger where game_id='a0000000-0000-0000-0000-000000000050' and game_table_id='b0000000-0000-0000-0000-000000000052'),11::bigint,'winner charged once');
select is((select count(*) from public.table_coin_ledger where game_id='a0000000-0000-0000-0000-000000000050' and correlation_id='70000000-0000-0000-0000-000000000707'),1::bigint,'close retry creates no duplicate debit');
insert into public.events(id,name) values('e0000000-0000-0000-0000-000000000701','No sale event');
insert into public.games(id,event_id,code,lifecycle,narrative_phase,scenario_version_id) values('a0000000-0000-0000-0000-000000000701','e0000000-0000-0000-0000-000000000701','NO-SALE','live','auction','e0000000-0000-0000-0000-000000000015');
insert into public.game_tables(id,game_id,table_number) values('b0000000-0000-0000-0000-000000000701','a0000000-0000-0000-0000-000000000701',1);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000701',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000701","role":"authenticated","is_anonymous":false}',true);
select is((select status from public.open_game_auction('NO-SALE','70000000-0000-0000-0000-000000000708')),'open','no-sale auction opens');
select is((select status from public.close_game_auction_no_sale('NO-SALE','70000000-0000-0000-0000-000000000709')),'no_sale','no-sale closes without bids');
select is((select winning_bid from public.get_staff_game_auction('NO-SALE')),null::integer,'no-sale has no winner');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000702',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000702","role":"authenticated","is_anonymous":false}',true);
select throws_ok($$select * from public.get_staff_game_auction('NO-SALE')$$,'P0001','STAFF_ACCESS_DENIED','non Staff denied auction read');
reset role;
select * from finish();
rollback;
